#!/usr/bin/env python3
"""Generate the manual dispatch workflow with a machine choice input from machines.json."""

import json


def sdk_name(machine):
    # SDK outputs are named after the architecture; the manual SDK workflow
    # rebuilds the kas machine path as "docker-<arch>".
    if not machine.startswith("docker-"):
        raise SystemExit(f"sdk_machines: {machine} must be a docker-<arch> machine")
    return machine[len("docker-"):]

with open(".github/machines.json") as f:
    data = json.load(f)

branch = data["yocto_branch"]
machines = [m for m in data["machines"] if "manual" in m.get("workflows", [])]
outfile = f".github/workflows/manual-{branch}.yaml"

machine_names = [m["name"] for m in machines]
options = "\n".join(f"          - {name}" for name in machine_names)

content = f"""\
# ##############################################################################
# DO NOT EDIT — auto-generated by .github/scripts/make-manual-dispatch.py
# Edit that script (and .github/machines.json), then run:
#   .github/scripts/makeworkflows
# Manual changes here will be overwritten on the next run.
# ##############################################################################

name: "manual: {branch}"

on:
  workflow_dispatch:
    inputs:
      machine:
        description: 'Machine to build'
        required: true
        type: choice
        options:
{options}

jobs:
  resolve:
    runs-on: ubuntu-latest
    outputs:
      configs: ${{{{ steps.lookup.outputs.configs }}}}
      build_target: ${{{{ steps.lookup.outputs.build_target }}}}
      output: ${{{{ steps.lookup.outputs.output }}}}
    steps:
      - uses: actions/checkout@v6
      - id: lookup
        run: |
          machine="${{{{ inputs.machine }}}}"
          build_target=$(jq -r ".machines[] | select(.name == \\"$machine\\") | .build_target // \\"pantavisor-starter\\"" .github/machines.json)
          output=$(jq -r ".machines[] | select(.name == \\"$machine\\") | .output // \\"pantavisor-starter*.rootfs.wic*\\"" .github/machines.json)
          echo "configs=kas/build-configs/release/$machine-{branch}.yaml:kas/build-configs/shared-vols.yaml" >> $GITHUB_OUTPUT
          echo "build_target=$build_target" >> $GITHUB_OUTPUT
          echo "output=$output" >> $GITHUB_OUTPUT

  build:
    needs: resolve
    uses: ./.github/workflows/buildkas-target.yaml
    with:
      configs: ${{{{ needs.resolve.outputs.configs }}}}
      machine_name: ${{{{ inputs.machine }}}}-{branch}
      build_target: ${{{{ needs.resolve.outputs.build_target }}}}
      output: ${{{{ needs.resolve.outputs.output }}}}
    secrets: inherit
"""

with open(outfile, "w") as f:
    f.write(content)

print(f"new manual dispatch workflow: {outfile}")

sdk_machines = data.get("sdk_machines", [])
sdk_outfile = f".github/workflows/manual-sdk-{branch}.yaml"
sdk_options = "\n".join(f"          - {sdk_name(name)}" for name in sdk_machines)

sdk_content = f"""\
# ##############################################################################
# DO NOT EDIT — auto-generated by .github/scripts/make-manual-dispatch.py
# Edit that script (and .github/machines.json), then run:
#   .github/scripts/makeworkflows
# Manual changes here will be overwritten on the next run.
# ##############################################################################

name: "manual: sdk {branch}"

on:
  workflow_dispatch:
    inputs:
      arch:
        description: 'Architecture to build the SDK for'
        required: true
        type: choice
        options:
{sdk_options}

jobs:
  build:
    uses: ./.github/workflows/buildkas-sdk.yaml
    with:
      configs: kas/machines/docker-${{{{ inputs.arch }}}}.yaml:kas/{branch}.yaml:kas/bsp-base.yaml:kas/sdk.yaml:kas/build-configs/shared-vols.yaml
      sdk_name: ${{{{ inputs.arch }}}}
    secrets: inherit
"""

with open(sdk_outfile, "w") as f:
    f.write(sdk_content)

print(f"new manual dispatch workflow: {sdk_outfile}")
